    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_codeplugme_core_fn_free_progresslistener(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_codeplugme_core_fn_clone_progresslistener(pointer!!, status)
        }
    }

    
    /**
     * Report that `done` of `total` blocks have moved.
     */override fun `onProgress`(`done`: kotlin.UInt, `total`: kotlin.UInt)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_codeplugme_core_fn_method_progresslistener_on_progress(
        it, FfiConverterUInt.lower(`done`),FfiConverterUInt.lower(`total`),_status)
}
    }
    
    

    

    
    
    companion object
    
}


// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceProgressListener {
    internal object `onProgress`: UniffiCallbackInterfaceProgressListenerMethod0 {
        override fun callback(`uniffiHandle`: Long,`done`: Int,`total`: Int,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeProgressListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onProgress`(
                    FfiConverterUInt.lift(`done`),
                    FfiConverterUInt.lift(`total`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeProgressListener.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceProgressListener.UniffiByValue(
        `onProgress`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_codeplugme_core_fn_init_callback_vtable_progresslistener(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeProgressListener: FfiConverter<ProgressListener, Pointer> {
    internal val handleMap = UniffiHandleMap<ProgressListener>()

    override fun lower(value: ProgressListener): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): ProgressListener {
        return ProgressListenerImpl(value)
    }

    override fun read(buf: ByteBuffer): ProgressListener {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ProgressListener) = 8UL

    override fun write(value: ProgressListener, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * One run of bytes that came back different from what was sent.
 *
 * `region` is the map label from `docs/qyt-kt5000-memory-map.md`, so a failure
 * reads as "12 bytes in channel names" rather than as a hex offset.
 */
data class ImageDiff (
    /**
     * First differing address.
     */
    var `addr`: kotlin.UInt, 
    /**
     * How many consecutive bytes differ.
     */
    var `len`: kotlin.UInt, 
    /**
     * The map region `addr` falls in.
     */
    var `region`: kotlin.String
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeImageDiff: FfiConverterRustBuffer<ImageDiff> {
    override fun read(buf: ByteBuffer): ImageDiff {
        return ImageDiff(
            FfiConverterUInt.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: ImageDiff) = (
            FfiConverterUInt.allocationSize(value.`addr`) +
            FfiConverterUInt.allocationSize(value.`len`) +
            FfiConverterString.allocationSize(value.`region`)
    )

    override fun write(value: ImageDiff, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`addr`, buf)
            FfiConverterUInt.write(value.`len`, buf)
            FfiConverterString.write(value.`region`, buf)
    }
}





/**
 * Every failure crossing this boundary, reduced to a message.
 *
 * The core's own [`crate::error::Error`] is richer, but the app only ever
 * displays these, and one variant keeps the generated Kotlin to a single type
 * whose message is always safe to show. This matches what the C ABI already
 * does with its `err_out` strings.
 *
 * **This must not be a `#[uniffi(flat_error)]`.** A flat error can only travel
 * Rust to host. UniFFI generates its `Lift` the other way as a `panic!("Can't
 * lift flat errors")`, and [`ByteTransport`] is a foreign trait that returns
 * this type, so the first failure the Kotlin transport reported panicked
 * inside the lift and replaced the real message with that one. Found on
 * hardware 2026-09-04, where every KT-5000 read surfaced as "Can't lift flat
 * errors" and the actual cause was invisible. A named field costs nothing and
 * crosses in both directions.
 */
sealed class ApiException: kotlin.Exception() {
    
    /**
     * Something went wrong; the message is user-facing.
     */
    class Failed(
        
        /**
         * Human-readable description of the failure.
         */
        val `msg`: kotlin.String
        ) : ApiException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): ApiException = FfiConverterTypeApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeApiError : FfiConverterRustBuffer<ApiException> {
    override fun read(buf: ByteBuffer): ApiException {
        

        return when(buf.getInt()) {
            1 -> ApiException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ApiException): ULong {
        return when(value) {
            is ApiException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: ApiException, buf: ByteBuffer) {
        when(value) {
            is ApiException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




